    'RegisterAndUpgradeDesc'              => 'SimpleRiskのインストールを登録し、サブスクリプションキーの入力または更新を行い、ワンクリックでCore/Extraのアップグレードを実行します。',
    'QueueMonitorDesc'                    => 'バックグラウンドジョブキューを確認します。保留中のジョブ、実行中のジョブ、失敗したジョブが表示されます。',
    'ExtrasDesc'                          => 'SimpleRisk Extras（有料アドオン）の有効化、無効化、および設定を行います。',
    'ArtificialIntelligenceExtraDesc'     => '人工知能エクストラは、強化されたリスク分析（FAIR評価を含む）とカスタマイズされたドキュメントを提供します。',
    'CustomizationExtraDesc'              => 'Customization Extraを使用すると、さまざまなタイプのフィールドを追加・削除し、カスタムページテンプレートを動的に作成できます。',
    'NotificationExtraDesc'               => 'メール通知エクストラを使用すると、リスクが提出、変更、またはその他のアクションが行われた際に、SimpleRiskからメール通知が送信されます。このエクストラは、リスクが管理レビューの準備が整った際に定期的なリマインダーを送信するスケジュールスクリプトとして追加することもできます。SimpleRisk Core製品では、このエクストラがない場合、ツール自体以外では通知は送信されません。',
    'VulnerabilityManagementExtraDesc'    => '脆弱性管理エクストラ機能を使用すると、SimpleRiskインスタンスをQualys、Tenable.io、またはRapid7 Nexpose/InsightVMと統合し、資産データと脆弱性データの両方をSimpleRiskにインポートできます。そこから、対象とするサイトを選択し、インポートする脆弱性スコアを決定し、どの脆弱性をリスクに変換して追跡するかをトリアージできます。',
    'IncidentManagementExtraDesc'         => 'インシデント管理エクストラは、NIST 800-61コンピュータセキュリティインシデント処理ガイドに基づいており、SimpleRiskシステム内からインシデント管理機能を提供します。',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'SimpleRiskのUI全体で使用されている用語（リスク、資産、フレームワークなど）の名前を変更します。',
    'RiskConfigurationDesc'               => 'リスクスコアリングのルールを設定します:レベル、リスク選好度、SLAしきい値、従来型/寄与要因型のリスク計算式。',
    'RiskAndThreatCatalogDesc'            => 'ドロップダウンで使用されるリスクと脅威の値のカタログを管理します。',
    'AddAndRemoveValuesDesc'              => 'リスクフィールドのドロップダウン値(場所、ソース、カテゴリ、チーム、テクノロジーなど)を管理します。',
    'AssetValuationDesc'                  => '資産評価スケールと資産ごとの評価上書き設定を行います。',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'ユーザーの追加、編集、無効化、リセット、パスワードポリシーの管理を行います。',
    'RoleManagementDesc'                  => 'ロールと、各ロールに付与される権限を定義します。',
    'TeamManagementDesc'                  => 'レコードの表示フィルタリングに使用するチームを作成および管理します。',
    'SeparationExtraDesc'                 => 'Team-Based Separation Extraは、リスクの閲覧を、そのリスクが割り当てられているチームのメンバーであるユーザーのみに制限します。SimpleRisk Core製品では、このExtraがない場合、すべてのユーザーがすべてのリスクを閲覧できます。',
    'CustomAuthenticationExtraDesc'       => 'カスタム認証エクストラは、Active DirectoryおよびSAML認証をサポートします。SimpleRisk Core製品では、このエクストラがない場合、SimpleRisk IDリポジトリに新規ユーザーを作成するしか方法がありません。',
    'EncryptionExtraDesc'                 => '暗号化データベース拡張機能は、ランダムなAES-256ビット暗号化キーを生成し、そのキーを使用して機密性の高いテキストを暗号化してから、SimpleRiskデータベースに挿入します。これにより、SimpleRiskアプリケーションを直接使用しない限り、誰もデータを閲覧したり変更したりすることができなくなります。',
    'OrganizationManagementDesc'          => 'Organizational Hierarchy Extraにより、任意の数のチームを含めることができる複数のビジネスユニットを定義できます。ユーザーは、さまざまなビジネスユニット配下の1つ以上のチームに割り当てることができます。これは、ユーザーが関連付けられていないチーム、ユーザー、アセットを表示・使用できるかどうかに影響します。',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'リスクを一括削除します。削除は元に戻せないため、慎重に使用してください。',
    'AuditTrailDesc'                      => 'ユーザーアクションのシステム監査ログを検索およびエクスポートします。',
    'ImportExportExtraDesc'               => 'Import-Export Extraを使用すると、CSVファイルのフィールドをSimpleRiskデータベースのフィールドにマッピングすることで、SimpleRiskにデータをインポートできます。サードパーティのスプレッドシートからの監査結果、別のツールからの脆弱性スキャン結果、CMDBからの資産などをインポートするために使用できます。また、SimpleRiskからリスク、軽減策、レビュー、またはこれら3つを組み合わせたレポートを含むCSVファイルをエクスポートすることもできます。',
    'JiraExtraDesc'                       => 'Jira Integration Extraを使用すると、Jiraインスタンスと双方向で連携できます。これにより、リスクをJira課題に関連付けたり、データ、ステータス、コメントを同期したりすることが可能になります。',
    'APIExtraDesc'                        => 'API Extraにより、お客様はRESTful APIを使用して他のアプリケーションとのスクリプト化された連携を作成し、高度な自動化を実現して既存のインフラストラクチャを活用できます。',
    'AdvancedSearchExtraDesc'             => 'Advanced Search Extraは、トップバーの検索ボックスを、リスク、フレームワーク、コントロール、ドキュメント、例外、テスト、監査、アセット、アセットグループを横断する単一の検索に変え、結果を詳しく確認できる専用の検索ページを提供します。ユーザーが閲覧を許可されているレコードのみが表示されます。',
    'AssessmentsExtraDesc'                => 'リスク評価エクストラでは、連絡先の定義、質問の作成（ロジックを含む）、アンケートテンプレートを使用した複数の質問の組み立て、アンケートの作成と連絡先への送信、アンケート結果の表示、結果に基づくリスクの追加、時間の経過に伴う結果の比較、外部でカスタマイズされた評価のインポートとエクスポート、リスク評価監査証跡の確認などの機能をユーザーに提供します。',
    'ActiveAssessmentsDesc'               => '現在進行中の評価を表示および管理します。',
    'WorkflowsExtraDesc'                  => 'Workflows Extraは、SimpleRisk内のイベントに応じてリスク管理アクションを自動化する、ビジュアルでイベント駆動型のワークフローエンジンを提供します。リスクの送信、更新、レビューなどの変更をトリガーとするワークフローを設計し、承認のルーティングや作業の割り当てを行い、手作業を介さずにプロセスを進行させることができます。',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extraは、Secure Controls FrameworkとSimpleRiskを直接統合したものです。SCFのコントロールカタログと、幅広いコンプライアンスおよびサイバーセキュリティフレームワークにおけるそれらのマッピングをSimpleRiskのガバナンス機能にインポートすることで、必要なフレームワークを採用し、コントロールを手動で構築することなく管理できます。",

