    'SoaExportRequiresNewerCore' => 'このエクスポートには、インストール済みのものより新しいバージョンのSimpleRisk Coreが必要です。SimpleRiskを更新してから、もう一度エクスポートをお試しください。',
    // The framework ACQUISITION chooser (Task 26): "+ Add framework" asks how you
