    'DamagePotentialHelp' => '脅威が悪用された場合、どの程度の損害が発生するでしょうか？' . "\n" . '0 = なし' . "\n" . '5 = 個々のユーザーデータが侵害または影響を受けている。' . "\n" . '10 = システムまたはデータの完全破壊',
    'ReproducibilityHelp' => '脅威のエクスプロイトを再現するのはどの程度容易か。
0 = アプリケーションの管理者であっても、非常に困難または不可能。
5 = 1～2ステップが必要で、認可されたユーザーである必要がある場合もある。
10 = Webブラウザとアドレスバーだけで十分で、認証は不要。',
    'ExploitabilityHelp' => 'この脅威を悪用するには何が必要か。
0 = 高度なプログラミングとネットワークの知識、およびカスタムまたは高度な攻撃ツール。
5 = インターネット上にマルウェアが存在する、または利用可能な攻撃ツールを使えば容易にエクスプロイトを実行できる。
10 = Webブラウザのみ',
    'AffectedUsersHelp' => '影響を受けるユーザーは何人ですか？' . "\n" . '0 = なし' . "\n" . '5 = 一部のユーザーだが、全員ではない' . "\n" . '10 = すべてのユーザー',
    'DiscoverabilityHelp' => 'この脅威を発見するのはどの程度容易か。
0 = 非常に困難から不可能。ソースコードまたは管理者アクセスが必要。
5 = 推測やネットワークトレースの監視で突き止められる。
9 = この種の欠陥の詳細が既に公開されており、検索エンジンで容易に見つけられる。
10 = 情報がWebブラウザのアドレスバーまたはフォームに表示されている。',
