9 = セキュリティ侵入のスキル',
    'MotiveHelp' => 'この脅威エージェントのグループは、この脆弱性を見つけて悪用する動機がどの程度あるか。
1 = 報酬が低い、またはなし
4 = 報酬の可能性あり
9 = 高い報酬',
    'OpportunityHelp' => 'この脅威エージェントのグループがこの脆弱性を見つけて悪用するには、どのようなリソースと機会が必要か。
