3 = 困難
7 = 容易
9 = 自動化ツールが利用可能',
    'EaseOfExploitHelp' => 'この脅威エージェントのグループが、この脆弱性を実際に悪用するのはどの程度容易か。
1 = 理論上のみ
3 = 困難
5 = 容易
9 = 自動化ツールが利用可能',
    'AwarenessHelp' => 'この脆弱性は、この脅威エージェントのグループにどの程度知られているか。
1 = 不明
