9 = 公知',
    'IntrusionDetectionHelp' => 'エクスプロイトが検出される可能性はどの程度か。
1 = アプリケーションでのアクティブな検出
3 = ログ記録およびレビュー済み
8 = ログ記録のみでレビューなし
9 = ログ記録なし',
    'LossOfConfidentialityHelp' => 'どの程度のデータが開示される可能性があり、その機密性はどの程度か。
