    'LossOfAccountabilityHelp' => '脅威エージェントの行動を個人まで追跡できるか。
1 = 完全に追跡可能
7 = 追跡できる可能性あり
9 = 完全に匿名',
    'FinancialDamageHelp' => 'エクスプロイトによってどの程度の金銭的被害が生じるか。
1 = 脆弱性の修正コスト未満
3 = 年間利益への軽微な影響
7 = 年間利益への重大な影響
9 = 破産',
    'ReputationDamageHelp' => 'エクスプロイトにより、事業に損害を与える評判の毀損が生じるか。
1 = 最小限の損害
4 = 主要顧客アカウントの喪失
