9 = ブランドの毀損',
    'NonComplianceHelp' => 'コンプライアンス違反によって、どの程度のエクスポージャーが生じるか。
2 = 軽微な違反
5 = 明確な違反
7 = 注目度の高い違反',
    'PrivacyViolationHelp' => 'どの程度の個人を特定できる情報が開示される可能性があるか。
3 = 1人
